    var boxes: map<string, AtomicBox<T>>
    var testsPassed: map<string, bool>

    predicate Valid()
      reads this
    {
      && forall name :: name in boxes ==> boxes[name].version > 0
      && forall name :: name in testsPassed ==> testsPassed[name] == true
    }

    method Initialize()
      ensures Valid()
      modifies this
    {
      boxes := map[];
      testsPassed := map[];
    }

